styleTag:
@import url('https://fonts.cdnfonts.com/css/minecrafter-alt');
@import url('https://fonts.cdnfonts.com/css/minecraft-4');

*{box-sizing:border-box}
html,body{
  width:100%;
  height:100%;
  margin:0;
  overflow:hidden;
  background:transparent;
}

.widget{
  --scale:1;
  width:100%;
  height:100%;
  display:flex;
  align-items:flex-start;
  justify-content:center;
  transform:scale(var(--scale));
  transform-origin:top center;
}

.hud{
  width:414px;
  height:92px;
  margin-top:5px;
  display:flex;
  align-items:center;
}

.wither-wrap{
  width:112px;
  height:92px;
  display:flex;
  align-items:center;
  justify-content:center;
  margin-right:-4px;
  z-index:2;
}

.wither{
  max-width:108px;
  max-height:90px;
  object-fit:contain;
  filter:drop-shadow(2px 3px 2px rgba(0,0,0,.65));
}

.slots-panel{
  height:70px;
  flex:1;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:7px;
  padding:7px 9px;
  background:#0b0d0d;
  border:4px solid #44494a;
  box-shadow:
    inset 0 0 0 3px #171a1a,
    inset 0 0 0 5px #050606,
    0 3px 0 #111;
  clip-path:polygon(
    5px 0,
    calc(100% - 5px) 0,
    100% 5px,
    100% calc(100% - 5px),
    calc(100% - 5px) 100%,
    5px 100%,
    0 calc(100% - 5px),
    0 5px
  );
}

.slot{
  width:56px;
  height:56px;
  display:grid;
  place-items:center;
  overflow:hidden;
  background:#101313;
  border:4px solid #3e4344;
  box-shadow:
    inset 0 0 0 2px #070808,
    0 2px 0 rgba(0,0,0,.5);
  opacity:.28;
  filter:grayscale(1) brightness(.45);
  transition:opacity .16s ease, filter .16s ease, border-color .16s ease;
}

.slot img{
  width:100%;
  height:100%;
  object-fit:contain;
  transform:scale(.98);
}

.slot.collected{
  opacity:1;
  filter:none;
  border-color:#ececec;
}

.counter-panel{
  width:108px;
  height:64px;
  margin-left:6px;
  display:flex;
  align-items:center;
  justify-content:center;
  color:#eee7df;
  background:#0b0d0e;
  border:4px solid #44494a;
  box-shadow:
    inset 0 0 0 3px #171a1b,
    inset 0 0 0 5px #050606,
    0 3px 0 #111;
  clip-path:polygon(
    5px 0,
    calc(100% - 5px) 0,
    100% 5px,
    100% calc(100% - 5px),
    calc(100% - 5px) 100%,
    5px 100%,
    0 calc(100% - 5px),
    0 5px
  );
  font-family:'Minecrafter Alt','Minecraft',monospace;
  font-size:37px;
  line-height:1;
  letter-spacing:0;
  text-shadow:
    2px 2px 0 #242424,
    3px 3px 0 #242424,
    4px 4px 0 #0d2339;
}

.slash{
  padding:0 4px;
  color:#73869b;
}

scriptTag:
(()=>{"use strict";

const unresolved=v=>typeof v==="string"&&/^\{[^{}]+\}$/.test(v.trim());

const num=(v,f=0)=>{
  if(v==null||unresolved(v))return f;
  const n=Number(String(v).trim().replace(",","."));
  return Number.isFinite(n)?n:f;
};

const clamp=(v,a,b)=>Math.min(Math.max(v,a),b);

const C={
  count:clamp(Math.round(num("{skullCount}",0)),0,3),
  scale:clamp(num("{overlayScale}",100),50,150)
};

const root=document.querySelector(".widget");
const countEl=document.getElementById("count");

function applyScale(){
  root.style.setProperty("--scale",C.scale/100);
}

function render(){
  countEl.textContent=C.count;

  for(let i=1;i<=3;i++){
    document.getElementById(`slot-${i}`)
      .classList.toggle("collected",i<=C.count);
  }
}

window.onLiveVariableUpdate=(name,value)=>{
  if(name==="skullCount"){
    C.count=clamp(Math.round(num(value,C.count)),0,3);
  }else if(name==="overlayScale"){
    C.scale=clamp(num(value,C.scale),50,150);
    applyScale();
  }
  render();
};

applyScale();
render();
})();
